    /**
     * Method to retrieve the Interview via InterviewFetchOneSummary
     * @param 	summary InterviewFetchOneSummary 
     * @return 	InterviewFetchOneResponse
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    public Interview getInterview( InterviewFetchOneSummary summary ) 
    throws ProcessingException, IllegalArgumentException {
    	
    	if( summary == null )
    		throw new IllegalArgumentException( "InterviewFetchOneSummary arg cannot be null" );
    	
    	Interview entity = null;
    	
        try {
        	// --------------------------------------
        	// validate the fetch one summary
        	// --------------------------------------    	
        	validator.validate( summary );    
        	
        	// --------------------------------------
        	// use queryGateway to send request to Find a Interview
        	// --------------------------------------
        	CompletableFuture<Interview> futureEntity = queryGateway.query(new FindInterviewQuery( new LoadInterviewFilter( summary.getInterviewId() ) ), ResponseTypes.instanceOf(Interview.class));
        	
        	entity = futureEntity.get();
        }
        catch( Exception exc ) {
            final String errMsg = "Unable to locate Interview with id " + summary.getInterviewId();
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }


